// n8n Code node: "List new Form D filings" (mode: Run Once for All Items).
//
// Reads the SEC daily index for every weekday since the last completed scan and
// lists the new Form D filings (type "D", not amendments) not yet processed.
// Only the index files are fetched here (1-4 requests), so this node stays far
// inside n8n Cloud's 60-second Code limit; the filings themselves are fetched by
// the HTTP Request node that follows, which handles batching and retries.
//
// The node has "Always Output Data" on: on a day with nothing to fetch it emits
// one empty item, so the rest of the flow still runs and posts the daily summary.

const UA = 'Your Name you@example.com';
const MAX_DAYS_BACK = 4;          // a Monday run covers Friday, plus a holiday
const MAX_FILINGS_PER_RUN = 450;  // a backlog after an outage drains over later runs

const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
const ymd = d => d.toISOString().slice(0, 10).replace(/-/g, '');
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function index(day) {
  const q = Math.floor((Number(day.slice(4, 6)) - 1) / 3) + 1;
  const url = `https://www.sec.gov/Archives/edgar/daily-index/${day.slice(0, 4)}/QTR${q}/form.${day}.idx`;
  for (let i = 1; i <= 3; i++) {
    try {
      return await this.helpers.httpRequest({ url, headers: { 'User-Agent': UA }, json: false });
    } catch (e) {
      const code = String(e.httpCode || e.statusCode || (e.response && e.response.status) || '');
      if (code === '403' || code === '404') return null;  // the SEC answers 403 for a missing index (holiday)
      if (i === 3) throw e;
      await sleep(2000 * i);
    }
  }
}

const now = new Date();
const due = [];
for (let back = MAX_DAYS_BACK; back >= 1; back--) {
  const d = new Date(now); d.setUTCDate(d.getUTCDate() - back);
  if ([0, 6].includes(d.getUTCDay())) continue;  // no filings at weekends
  if (!state.lastScanned || ymd(d) > state.lastScanned) due.push(ymd(d));
}

const run = { at: now.toISOString(), daysChecked: [], noIndexDays: [], indexErrors: 0, listed: 0, deferredDays: [] };
const filings = [];
for (const day of due) {
  let idx;
  try { idx = await index.call(this, day); } catch (e) { run.indexErrors++; break; }  // retry from here next run
  run.daysChecked.push(day);
  if (!idx) { run.noIndexDays.push(day); continue; }
  for (const line of idx.split('\n')) {
    if (!/^D\s{2,}/.test(line)) continue;
    const m = line.match(/edgar\/data\/(\d+)\/(\S+)\.txt/);
    if (!m || state.seen[m[2]]) continue;
    filings.push({ day, cik: m[1], accession: m[2],
                   xmlUrl: `https://www.sec.gov/Archives/edgar/data/${m[1]}/${m[2].replace(/-/g, '')}/primary_doc.xml` });
  }
}

const work = filings.slice(0, MAX_FILINGS_PER_RUN);
run.listed = work.length;
run.deferredDays = [...new Set(filings.slice(MAX_FILINGS_PER_RUN).map(f => f.day))];
state.pendingRun = run;  // picked up by the match node

return work.map(f => ({ json: f }));

// n8n Code node: "Match against self-administered managers" (mode: Run Once for All Items).
//
// Input: one item per filing from the HTTP Request node (the Form D XML in
// `xml`, or an error item if the fetch failed after its retries). Keeps fund
// offerings whose general partner, manager or fund name matches a known
// self-administered manager, marks filings as seen, advances the scan cursor,
// and emits the alerts plus one summary item. The matching list is injected
// when the private workflow is generated; the public copy ships it empty.

const LOOKUP = {} /* removed from the public copy */;      // { normalisedName: crd }
const MANAGERS = {} /* removed from the public copy */;  // { crd: { manager, tier, score, shortlist, contact, title, opener } }

const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
state.runs = state.runs || [];
const run = state.pendingRun || { daysChecked: [], noIndexDays: [], indexErrors: 0, listed: 0, deferredDays: [] };
delete state.pendingRun;

const SUFFIX = /\b(LLC|L L C|LP|L P|LLLP|INC|CORP|CORPORATION|CO|COMPANY|LTD|LIMITED|THE)\b/g;
const norm = s => String(s || '').toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(SUFFIX, ' ').split(/\s+/).filter(Boolean).join(' ');
const tag = (xml, name) => { const m = xml.match(new RegExp(`<${name}>([\\s\\S]*?)</${name}>`)); return m ? m[1].trim() : ''; };
const FUND_TYPES = ['Private Equity Fund', 'Other Investment Fund'];
const RE_GROUPS = ['Other Real Estate', 'Commercial', 'Residential', 'REITS and Finance'];

const listed = $('List new Form D filings').all();
const results = $input.all();
const failedDays = new Set(run.deferredDays);
const alerts = [];
Object.assign(run, { formD: 0, funds: 0, matched: 0, errors: run.indexErrors });

results.forEach((item, i) => {
  const f = listed[item.pairedItem?.item ?? i]?.json;
  if (!f || !f.accession) return;  // the empty item on a day with nothing to fetch
  run.formD++;
  const xml = typeof item.json.xml === 'string' ? item.json.xml : '';
  if (!xml.includes('<edgarSubmission')) { run.errors++; failedDays.add(f.day); return; }
  state.seen[f.accession] = f.day;

  const fundType = tag(xml, 'investmentFundType');
  const industry = tag(xml, 'industryGroupType');
  if (!FUND_TYPES.includes(fundType) && !RE_GROUPS.includes(industry)) return;
  run.funds++;

  const issuer = tag(xml, 'entityName');
  const entities = [...xml.matchAll(/<relatedPersonName>([\s\S]*?)<\/relatedPersonName>/g)]
    .map(m => ({ first: tag(m[1], 'firstName'), last: tag(m[1], 'lastName') }))
    .filter(p => ['N/A', 'NA', ''].includes(p.first.toUpperCase()))
    .map(p => p.last);
  const matchedOn = [issuer, ...entities].find(n => LOOKUP[norm(n)]);
  if (!matchedOn) return;
  run.matched++;
  const crd = LOOKUP[norm(matchedOn)];
  const folder = `https://www.sec.gov/Archives/edgar/data/${f.cik}/${f.accession.replace(/-/g, '')}/`;
  alerts.push({ type: 'alert', filed: f.day, accession: f.accession, issuer, matchedOn,
                fundType: fundType || industry, amount: tag(xml, 'totalOfferingAmount'),
                crd, ...(MANAGERS[crd] || {}), filingUrl: folder,
                adviserUrl: `https://adviserinfo.sec.gov/firm/summary/${crd}` });
});

// Advance the cursor past every checked day whose filings were all processed.
for (const day of [...run.daysChecked].sort()) {
  if (failedDays.has(day)) break;
  state.lastScanned = day;
}
const cutoff = new Date(Date.now() - 30 * 864e5).toISOString().slice(0, 10).replace(/-/g, '');
for (const [acc, day] of Object.entries(state.seen)) if (day < cutoff) delete state.seen[acc];
state.runs.push(run);
state.runs = state.runs.slice(-200);

return [
  ...alerts.map(a => ({ json: a })),
  { json: { type: 'summary', ...run, deferred: run.deferredDays.length,
            runsSoFar: state.runs.length,
            matchesSoFar: state.runs.reduce((s, r) => s + (r.matched || 0), 0),
            errorsSoFar: state.runs.reduce((s, r) => s + (r.errors || 0), 0) } },
];

// n8n Code node: "Format Slack messages" (mode: Run Once for All Items).
// One message per matched filing, plus a daily summary so quiet days still
// prove the job ran.

const money = v => (/^\d+$/.test(v || '') ? '$' + (Number(v) / 1e6).toFixed(1) + 'M' : 'amount not stated');
const day = d => `${d.slice(0, 4)}-${d.slice(4, 6)}-${d.slice(6)}`;
const items = $input.all().map(i => i.json);
const out = [];

// One message per manager per filing day, listing every new fund it filed.
const groups = {};
for (const a of items.filter(a => a.type === 'alert')) (groups[`${a.crd}|${a.filed}`] ||= []).push(a);

for (const group of Object.values(groups)) {
  const a = group[0];
  const priority = a.tier === 'A' || a.tier === 'B';
  const funds = group.map(g => `• ${g.issuer} (${g.fundType}, ${money(g.amount)}) <${g.filingUrl}|filing>`);
  const lines = [
    `${priority ? ':rotating_light: *Priority*' : ':eyes: *Watchlist*'}: *${a.manager || a.matchedOn}* filed `
      + `${group.length === 1 ? 'a new fund' : `${group.length} new funds`} on ${day(a.filed)}`,
    ...funds,
    `*Why it matters:* this manager runs its existing PE/RE funds without an outside administrator`
      + (priority ? `. Tier ${a.tier}${a.score != null ? `, v2 score ${(a.score * 100).toFixed(1)}%` : ''}`
                    + `${a.shortlist ? ', on the outreach shortlist' : ''}.` : '.'),
  ];
  if (a.contact) lines.push(`*Contact:* ${a.contact}${a.title ? ` (${a.title})` : ''}`);
  if (a.opener) lines.push(`*Draft opener:*\n>${a.opener.replace(/\n/g, '\n>')}`);
  lines.push(`<${a.adviserUrl}|SEC adviser profile> · matched on "${a.matchedOn}"`);
  out.push({ json: { slack: { text: lines.join('\n') } } });
}

for (const a of items.filter(a => a.type === 'summary')) {
  const days = a.daysChecked.length ? a.daysChecked.map(day).join(', ') : 'none due';
  out.push({ json: { slack: { text:
    `:white_check_mark: Daily scan done. Days: ${days}. Form D filings checked: ${a.formD}, `
    + `fund offerings: ${a.funds}, matches: *${a.matched}* (${Object.keys(groups).length} alert${Object.keys(groups).length === 1 ? '' : 's'}), errors: ${a.errors}`
    + (a.deferred ? `, days deferred to next run: ${a.deferred}` : '')
    + (a.noIndexDays.length ? `, no SEC index (holiday?): ${a.noIndexDays.map(day).join(', ')}` : '')
    + `. Run #${a.runsSoFar}: ${a.matchesSoFar} matches and ${a.errorsSoFar} errors so far.` } } });
}
return out;
